per_hop.query:
SELECT ?show ?host WHERE {
  ?show rdf:type mtv:TVShow ;
        mtv:title "You Can't See Me" ;
        mtv:host ?host .
  ?host rdf:type mtv:Person .

  ?band mtv:hasMember ?host .
  ?band mtv:hasMember ?defari .
  ?defari mtv:stageName "Defari" .
}

SELECT ?series ?premiereDate WHERE {
  ?actor dbo:character dbr:Gaius_Baltar ;
         dbo:starring ?series .
  ?series dbo:premiereDate ?premiereDate .
  FILTER(datatype(?premiereDate) = xsd:date)
} ORDER BY ?premiereDate

SELECT ?series ?premiereDate WHERE {
  ?actor dbo:character dbr:Gaius_Baltar ;
         dbo:starring ?series .
  ?series dbo:premiereDate ?premiereDate .
  FILTER(datatype(?premiereDate) = xsd:date)
} ORDER BY ?premiereDate

SELECT ?actor WHERE {
  ?performance1 dbo:performance ?performanceEvent1 .
  ?performanceEvent1 dbo:musicVenue dbr:Dorothy_Chandler_Pavilion ;
                   dbo:title "Hollywood Goes Classical"@en ;
                   dbo:starring ?actor .
  ?film dbo:starring ?actor ;
        rdfs:label "Lethal Obsession"@en .
  ?actor dbo:birthPlace ?birthPlace .
  ?birthPlace dbo:country dbr:England .
}

SELECT ?actor WHERE {
  ?performance1 dbo:performance ?performanceEvent1 .
  ?performanceEvent1 dbo:musicVenue dbr:Dorothy_Chandler_Pavilion ;
                   dbo:title "Hollywood Goes Classical"@en ;
                   dbo:starring ?actor .
  ?film dbo:starring ?actor ;
        rdfs:label "Lethal Obsession"@en .
  ?actor dbo:birthPlace ?birthPlace .
  ?birthPlace dbo:country dbr:England .
}

SELECT ?show WHERE {
  ?band ?p ?defari .
  ?defari rdf:type :StreetMusicArtist, :HipHopMusician ;
          :memberOf ?band .
  ?member :memberOf ?band ;
          :hostedMTVShow ?show .
  FILTER(CONTAINS(LCASE(STR(?show)), "you can't see me"))
}

SELECT ?host ?totalHostedShows WHERE {
  ?show wdt:P921 wd:Q123456 ;       # The specific TV show Paul Melba appeared on (need to identify)
        wdt:P495 wd:Q145 .           # Country of origin is United Kingdom (British version)
  ?appearance wdt:P642 ?show ;
              wdt:P161 wd:Q56789 .    # Paul Melba as a participant/guest
  ?show wdt:P708 ?host .             # The show's host
  ?host wdt:P1342 ?totalHostedShows . # Number of shows hosted by the host
  FILTER(?totalHostedShows = 23)
}

